1	//! What the experimental TypeScript checker backend hands back, and how it merges over the structural result.
2	//!
3	//! The backend (`caliper-docgen-semantic`) owns the process, the protocol and the checker walk; this module owns only
4	//! the result shape and the merge rules of `docs/type-checker-integration.md`, so `crates/core` stays free of I/O.
5	
6	use std::collections::BTreeMap;
7	use std::hash::{Hash, Hasher};
8	use std::sync::{Arc, Mutex};
9	
10	use camino::Utf8PathBuf;
11	use rustc_hash::{FxHashMap, FxHasher};
12	
13	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
14	use crate::types::output::{ComponentEntry, ExtractionOutput, ParsedProp, PropType};
15	
16	/// One prop as the checker reports it.
17	#[derive(Debug, Clone, PartialEq)]
18	pub struct SemanticProp {
19	    pub name: String,
20	    pub prop_type: PropType,
21	    pub required: bool,
22	    pub description: String,
23	    /// Declared by `@types/react` (`children`, `aria-*`, handlers, `className`): not the component's own prop.
24	    pub react_declared: bool,
25	}
26	
27	impl SemanticProp {
28	    fn structural_hash(&self) -> u64 {
29	        let mut hasher = FxHasher::default();
30	        self.name.hash(&mut hasher);
31	        self.required.hash(&mut hasher);
32	        self.react_declared.hash(&mut hasher);
33	        self.description.hash(&mut hasher);
34	        self.prop_type.structural_hash(&mut hasher);
35	        hasher.finish()
36	    }
37	}
38	
39	/// Shares identical props between components, as the structural resolver does: a design system's components repeat
40	/// the same few hundred props, and Chakra's 600 components would otherwise hold 470,000 copies.
41	#[derive(Debug, Default)]
42	pub struct PropInterner {
43	    by_hash: Mutex<FxHashMap<u64, Vec<Arc<SemanticProp>>>>,
44	}
45	
46	impl PropInterner {
47	    pub fn share(&self, prop: SemanticProp) -> Arc<SemanticProp> {
48	        let hash = prop.structural_hash();
49	        let Ok(mut by_hash) = self.by_hash.lock() else { return Arc::new(prop) };
50	        let bucket = by_hash.entry(hash).or_default();
51	        if let Some(existing) = bucket.iter().find(|existing| ***existing == prop) {
52	            return existing.clone();
53	        }
54	        let shared = Arc::new(prop);
55	        bucket.push(shared.clone());
56	        shared
57	    }
58	}
59	
60	/// One component the checker answered for, found by the file and name the structural pass reported.
61	#[derive(Debug, Clone, PartialEq)]
62	pub struct SemanticComponent {
63	    pub file_path: Utf8PathBuf,
64	    pub display_name: String,
65	    /// Declared props in declaration order, with the `@types/react` ones the request asked for.
66	    pub props: Vec<Arc<SemanticProp>>,
67	}
68	
69	/// A component the backend left to the structural result, and why.
70	#[derive(Debug, Clone, PartialEq, Eq)]
71	pub struct SemanticFallback {
72	    pub file_path: Utf8PathBuf,
73	    pub display_name: String,
74	    pub reason: String,
75	}
76	
77	/// The backend's answer for a run. A backend that could not start returns no components and one diagnostic, never an
78	/// error: the structural result is always a complete answer on its own.
79	#[derive(Debug, Clone, Default, PartialEq)]
80	pub struct SemanticOutcome {
81	    pub components: Vec<SemanticComponent>,
82	    pub fallbacks: Vec<SemanticFallback>,
83	    pub diagnostics: Vec<Diagnostic>,
84	}
85	
86	/// A component the checker may be asked about.
87	#[derive(Debug, Clone, PartialEq, Eq)]
88	pub struct SemanticTarget {
89	    pub file_path: Utf8PathBuf,
90	    pub display_name: String,
91	    pub exported: bool,
92	    /// Props the structural pass already has a description for. The checker is not asked for those: it is 65% of
